"""Verify the ONLYOFFICE host generated by native MCEL DSL compilation.

The viewport projects the interface directly; no HTML snapshot is written.
"""
from __future__ import annotations

import argparse
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from main_computer.mcel_onlyoffice_host_projection import project


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="Verify native MCEL projection (default behavior)")
    parser.parse_args()

    html = project(ROOT)
    if not html.strip():
        raise SystemExit("FAIL: Native MCEL ONLYOFFICE host projection produced empty HTML")
    print("PASS: Native MCEL ONLYOFFICE host projection")


if __name__ == "__main__":
    main()
